-- The order gateway (ADR-0025, prompt_phase_s3.md §§7, 10, 11).
--
-- 1. Tables and enums — generated by `prisma migrate diff`, not hand-written.
-- 2. Grants and append-only triggers for the order history.
-- 3. The legal-transition trigger — GENERATED from ORDER_TRANSITIONS in
--    packages/types/src/order-states.ts. CI checks the VALUES list below
--    against that table (scripts/check-transition-constraints.mjs).
-- 4. Structural constraints the type system cannot see past raw SQL.

-- ---------------------------------------------------------------------------
-- 1. Schema (prisma migrate diff)
-- ---------------------------------------------------------------------------
-- CreateEnum
CREATE TYPE "WithdrawalPurpose" AS ENUM ('external', 'allocation', 'deallocation');

-- CreateEnum
CREATE TYPE "OrderStatus" AS ENUM ('PENDING_ENGINE', 'OPEN', 'PARTIALLY_FILLED', 'PENDING_CANCEL', 'FILLED', 'CANCELLED', 'REJECTED', 'EXPIRED', 'FAILED');

-- CreateEnum
CREATE TYPE "OrderSide" AS ENUM ('buy', 'sell');

-- CreateEnum
CREATE TYPE "OrderKind" AS ENUM ('limit', 'market');

-- CreateEnum
CREATE TYPE "OrderTimeInForce" AS ENUM ('GTC', 'IOC', 'FOK');

-- AlterTable
ALTER TABLE "withdrawals" ADD COLUMN     "purpose" "WithdrawalPurpose" NOT NULL DEFAULT 'external';

-- CreateTable
CREATE TABLE "orders" (
    "id" UUID NOT NULL,
    "user_id" UUID NOT NULL,
    "client_order_id" TEXT NOT NULL,
    "market" TEXT NOT NULL,
    "side" "OrderSide" NOT NULL,
    "kind" "OrderKind" NOT NULL,
    "time_in_force" "OrderTimeInForce" NOT NULL,
    "post_only" BOOLEAN NOT NULL,
    "price" DECIMAL(38,0),
    "qty" DECIMAL(38,0) NOT NULL,
    "filled_qty" DECIMAL(38,0) NOT NULL DEFAULT 0,
    "status" "OrderStatus" NOT NULL DEFAULT 'PENDING_ENGINE',
    "hold_asset" TEXT NOT NULL,
    "hold_amount" DECIMAL(38,0) NOT NULL,
    "hold_ledger_transaction_id" UUID NOT NULL,
    "engine_seq" BIGINT,
    "reject_reason" TEXT,
    "sweep_attempts" INTEGER NOT NULL DEFAULT 0,
    "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(3) NOT NULL,

    CONSTRAINT "orders_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "order_transitions" (
    "id" UUID NOT NULL,
    "order_id" UUID NOT NULL,
    "from_status" "OrderStatus",
    "to_status" "OrderStatus" NOT NULL,
    "reason" TEXT,
    "correlation_id" TEXT,
    "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "order_transitions_pkey" PRIMARY KEY ("id")
